function cd_h($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$stats=['total'=>0,'published'=>0,'pending'=>0,'changes'=>0,'views'=>0,'likes'=>0,'chapters'=>0];
$q=$pdo->prepare("SELECT COUNT(*) total, SUM(status='published') published, COALESCE(SUM(views_count),0) views, COALESCE(SUM(likes_count),0) likes FROM stories WHERE member_id=?");
$q->execute([$memberId]);$row=$q->fetch()?:[];
foreach(['total','published','views','likes'] as $key)$stats[$key]=(int)($row[$key]??0);
$q=$pdo->prepare("SELECT COUNT(*) FROM stories s LEFT JOIN story_moderation_reviews r ON r.target_type='story' AND r.target_id=s.id WHERE s.member_id=? AND s.status<>'published' AND (r.decision IS NULL OR r.decision<>'rejected')");
$q->execute([$memberId]);$stats['pending']=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT COUNT(*) FROM stories s JOIN story_moderation_reviews r ON r.target_type='story' AND r.target_id=s.id AND r.decision='rejected' WHERE s.member_id=? AND s.status<>'published'");
$q->execute([$memberId]);$stats['changes']=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT COUNT(*) FROM chapters c JOIN stories s ON s.id=c.story_id WHERE s.member_id=?");
$q->execute([$memberId]);$stats['chapters']=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT s.id,s.title,s.slug,s.story_kind,s.story_type,s.status,s.created_at,s.views_count,s.likes_count,r.decision review_decision,r.note review_note,(SELECT COUNT(*) FROM chapters c WHERE c.story_id=s.id) chapter_count FROM stories s LEFT JOIN story_moderation_reviews r ON r.target_type='story' AND r.target_id=s.id WHERE s.member_id=? ORDER BY s.created_at DESC,s.id DESC LIMIT 8");
$q->execute([$memberId]);$recent=$q->fetchAll();
$q=$pdo->prepare("SELECT s.id,s.title,s.slug,s.views_count,s.likes_count FROM stories s WHERE s.member_id=? AND s.status='published' ORDER BY s.views_count DESC,s.likes_count DESC LIMIT 3");
$q->execute([$memberId]);$topStories=$q->fetchAll();
$monthly=array_fill(0,6,0);$monthLabels=[];$monthKeys=[];
for($i=5;$i>=0;$i--){$d=new DateTimeImmutable('first day of this month');$d=$d->modify('-'.$i.' months');$monthKeys[]=$d->format('Y-m');$monthLabels[]=$d->format('m/Y');}
$q=$pdo->prepare("SELECT DATE_FORMAT(created_at,'%Y-%m') ym,COUNT(*) total FROM stories WHERE member_id=? AND created_at>=DATE_FORMAT(DATE_SUB(CURDATE(),INTERVAL 5 MONTH),'%Y-%m-01') GROUP BY ym");
$q->execute([$memberId]);$monthlyRows=$q->fetchAll();$monthlyMap=[];foreach($monthlyRows as $mr)$monthlyMap[$mr['ym']]=(int)$mr['total'];foreach($monthKeys as $i=>$key)$monthly[$i]=$monthlyMap[$key]??0;
$maxMonthly=max(1,max($monthly));

$rewardTotals=['pending'=>0,'paid'=>0,'total'=>0];$rewardRows=[];$rewardTableMissing=false;
try{$q=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN payment_status='pending' THEN amount ELSE 0 END),0) pending,COALESCE(SUM(CASE WHEN payment_status='paid' THEN amount ELSE 0 END),0) paid,COALESCE(SUM(amount),0) total FROM contributor_rewards WHERE member_id=?");$q->execute([$memberId]);$rewardTotals=$q->fetch()?:$rewardTotals;$q=$pdo->prepare('SELECT amount,reward_type,description,period_label,payment_status,created_at FROM contributor_rewards WHERE member_id=? ORDER BY created_at DESC,id DESC LIMIT 8');$q->execute([$memberId]);$rewardRows=$q->fetchAll();}catch(Throwable $e){$rewardTableMissing=true;}
function cd_rank(int $published,int $views):array{if($published>=20||$views>=50000)return ['Tác giả tiêu biểu','featured','✦'];if($published>=10||$views>=10000)return ['Tác giả chính thức','official','◆'];if($published>=3||$views>=2000)return ['Cây bút triển vọng','rising','✍'];return ['CTV mới','new','✧'];}
$creatorRank=cd_rank($stats['published'],$stats['views']);
$achievements=[];if($stats['published']>=1)$achievements[]=['✦','Tác giả ra mắt','Đã có truyện xuất bản'];if($stats['published']>=5)$achievements[]=['✍','Cây bút bền bỉ','Xuất bản từ 5 truyện'];if($stats['views']>=1000)$achievements[]=['◉','Người kể chuyện','Đạt 1.000 lượt đọc'];if($stats['views']>=10000)$achievements[]=['✧','Được độc giả yêu thích','Đạt 10.000 lượt đọc'];if($stats['likes']>=100)$achievements[]=['♥','Được độc giả mến mộ','Đạt 100 lượt thích'];if($stats['chapters']>=20)$achievements[]=['▤','Người viết trường thiên','Đăng từ 20 chương'];

function cd_status(array $s):array{if(($s['status']??'')==='published')return ['Đã xuất bản','published'];if(($s['review_decision']??'')==='rejected')return ['Cần chỉnh sửa','changes'];if(($s['review_decision']??'')==='approved')return ['Đã duyệt','approved'];return ['Chờ kiểm duyệt','pending'];}
function cd_url(array $s):string{return ($s['story_type']==='audio'?'/audio/':(($s['story_kind']??'')==='short'?'/truyen-ngan/':'/truyen/')).rawurlencode((string)$s['slug']).'.html';}
