<?=number_format($stats['published'])?></strong><small>Đang hiển thị trên web</small></article><article class="creator-stat"><span>Chờ xử lý</span><strong><?=number_format($stats['pending'])?></strong><small><?=$stats['changes']?> bài cần chỉnh sửa</small></article><article class="creator-stat"><span>Tổng lượt đọc</span><strong><?=number_format($stats['views'])?></strong><small><?=$stats['likes']?> lượt thích · <?=$stats['chapters']?> chương</small></article></section><section class="creator-section"><div class="creator-section-head"><h2>Nhịp sáng tác · 6 tháng gần đây</h2><span class="creator-footnote">Số truyện gửi theo tháng</span></div><div class="creator-chart"><?php foreach($monthly as $i=>$count):?><div class="creator-month"><strong><?=$count?></strong><div class="creator-bar-track"><div class="creator-bar" style="height:<?=max(3,(int)round($count/$maxMonthly*100))?>%"></div></div><small><?=cd_h($monthLabels[$i])?></small></div><?php endforeach;?></div></section><section class="creator-section" id="rewards"><div class="creator-section-head"><h2>Nhuận bút & thưởng</h2><span class="creator-footnote">Số liệu do ban quản trị ghi nhận</span></div><div class="creator-reward-grid"><article><span>Tổng ghi nhận</span><strong><?=number_format((float)$rewardTotals['total'],0,',','.')?>đ</strong></article><article><span>Chờ thanh toán</span><strong><?=number_format((float)$rewardTotals['pending'],0,',','.')?>đ</strong></article><article><span>Đã thanh toán</span><strong><?=number_format((float)$rewardTotals['paid'],0,',','.')?>đ</strong></article></div><?php if($rewardTableMissing):?><p class="creator-footnote">Sổ nhuận bút đang chờ quản trị viên cài đặt dữ liệu.</p><?php elseif(!$rewardRows):?><div class="creator-empty">Chưa có khoản nhuận bút nào được ghi nhận.</div><?php else:?><div class="creator-list"><?php foreach($rewardRows as $r):?><article class="creator-reward-row"><div><strong><?=cd_h(['royalty'=>'Nhuận bút','bonus'=>'Thưởng','adjustment'=>'Điều chỉnh'][$r['reward_type']]??$r['reward_type'])?> · <?=cd_h($r['description'])?></strong><small><?=cd_h($r['period_label'])?> · <?=cd_h(date('d/m/Y',strtotime($r['created_at'])))?></small></div><div class="creator-reward-amount"><strong><?=number_format((float)$r['amount'],0,',','.')?>đ</strong><span class="<?=cd_h($r['payment_status'])?>"><?=$r['payment_status']==='paid'?'Đã thanh toán':'Chờ thanh toán'?></span></div></article><?php endforeach;?></div><?php endif;?></section><section class="creator-section"><div class="creator-section-head"><h2>Huy hiệu thành tích</h2><span class="creator-footnote"><?=count($achievements)?> huy hiệu đạt được</span></div><?php if(!$achievements):?><div class="creator-empty">Hãy xuất bản truyện và kết nối với độc giả để mở khóa huy hiệu đầu tiên.</div><?php else:?><div class="creator-achievements"><?php foreach($achievements as $a):?><article><span><?=$a[0]?></span><div><strong><?=cd_h($a[1])?></strong><small><?=cd_h($a[2])?></small></div></article><?php endforeach;?></div><?php endif;?></section><div class="creator-layout"><section class="creator-section"><div class="creator-section-head"><h2>Bài viết gần đây</h2><a href="/submit_story.php#my-stories">Xem tất cả →</a></div><?php if(!$recent):?><div class="creator-empty">Bạn chưa gửi truyện nào. <a href="/submit_story.php">Bắt đầu sáng tác ngay</a>.</div><?php else:?><div class="creator-list"><?php foreach($recent as $s):[$statusLabel,$statusClass]=cd_status($s);?><article class="creator-story"><div class="creator-story-copy"><strong><?=cd_h($s['title'])?></strong><small><?=($s['story_type']==='audio'?'Audio':(($s['story_kind']??'')==='short'?'Truyện ngắn':'Truyện nhiều chương'))?> · <?=number_format((int)$s['views_count'])?> lượt đọc · <?=number_format((int)$s['likes_count'])?> thích · <?=cd_h(date('d/m/Y',strtotime($s['created_at'])))?></small><?php if(!empty($s['review_note'])):?><small>Góp ý: <?=cd_h($s['review_note'])?></small><?php endif;?></div><div class="creator-story-actions"><span class="creator-pill <?=cd_h($statusClass)?>"><?=cd_h($statusLabel)?></span><a href="/edit_story.php?id=<?=(int)$s['id']?>">Sửa</a><?php if($s['status']==='published'):?><a href="<?=cd_h(cd_url($s))?>">Xem</a><?php endif;?></div></article><?php endforeach;?></div><?php endif;?></section><section class="creator-section"><div class="creator-section-head"><h2>Truyện nổi bật</h2><a href="/submit_story.php#my-stories">Quản lý →</a></div><?php if(!$topStories):?><div class="creator-empty">Truyện đã xuất bản sẽ xuất hiện ở đây.</div><?php else:?><?php foreach($topStories as $s):?><div class="creator-top-item"><strong><?=cd_h($s['title'])?></strong><small>◉ <?=number_format((int)$s['views_count'])?> · ♥ <?=number_format((int)$s['likes_count'])?></small></div><?php endforeach;?><?php endif;?><p class="creator-footnote">Lượt đọc được lấy từ bộ đếm của từng truyện đã xuất bản. Biểu đồ tính theo ngày gửi truyện.</p></section></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>